"use client";

import { LedType } from "@/types/led";

interface LedPreviewProps {
  left1Label: LedType;
  left2Label: LedType;
  left3Label: LedType;
  right1Label: LedType;
  right2Label: LedType;
  right3Label: LedType;
}

const COLORS: Record<LedType, string> = {
  FX: "bg-blue-500 shadow-[0_0_8px_#3b82f6]",
  TX: "bg-yellow-400 shadow-[0_0_8px_#facc15]",
  LINK: "bg-green-500 shadow-[0_0_8px_#22c55e]",
  PWR: "bg-red-500 shadow-[0_0_8px_#ef4444]",
  ACT: "bg-purple-500 shadow-[0_0_8px_#a855f7]",
  FDX: "bg-cyan-400 shadow-[0_0_8px_#22d3ee]",
};

function PreviewLED({ label }: { label: LedType }) {
  return (
    <div className="flex items-center gap-2 rounded-lg border border-zinc-800 bg-zinc-950 px-2.5 py-1.5">
      <div className={`h-2 w-2 shrink-0 animate-pulse rounded-full ${COLORS[label]}`} />
      <span className="text-xs font-medium text-zinc-300">{label}</span>
    </div>
  );
}

export default function LedPreview({
  left1Label,
  left2Label,
  left3Label,
  right1Label,
  right2Label,
  right3Label,
}: LedPreviewProps) {
  return (
    <div>
      <p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.2em] text-zinc-500">
        Live Preview
      </p>

      <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-3">
        <PreviewLED label={left1Label} />
        <PreviewLED label={left2Label} />
        <PreviewLED label={left3Label} />
        <PreviewLED label={right1Label} />
        <PreviewLED label={right2Label} />
        <PreviewLED label={right3Label} />
      </div>
    </div>
  );
}
